import{_ as l,l as s,o as a,c as i,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"内核抢占","description":"","frontmatter":{"title":"内核抢占","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-preempt.md","filePath":"cs/kernel-preempt.md","lastUpdated":1789023840000}'),h={name:"cs/kernel-preempt.md"};function m(_,e,E,u,A,f){const o=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="内核抢占" tabindex="-1">内核抢占 <a class="header-anchor" href="#内核抢占" aria-label="Permalink to &quot;内核抢占&quot;">​</a></h1><div class="epigraph"><p>若内核在处理系统调用时不可抢占，高优先级线程必须等当前调用主动让出；打开抢占后，调度点遍布内核，锁与 per-CPU 的纪律必须更严。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 整理</footer></div><p><a href="/cs/nmi">上一课</a>说明连关中断都不能挡住一类入口。普通路径上，问题换成另一问：内核正在跑某线程的系统调用时，时钟中断来了，<strong>能不能立刻切到另一条更高优先级的内核/用户线程</strong>。传统 Unix 内核在返回用户前才调度（非抢占内核）；抢占内核在不持有自旋锁、抢占计数为零时允许切换。缺口是这道开关，不是 NMI 栈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非抢占：内核路径一直跑到睡眠或返回用户，实时任务的延迟等于「当前系统调用剩余」。抢占：中断返回内核时若 need_resched 且允许抢占，则<a href="/cs/context-switch">上下文切换</a>。缺口是：哪些区间禁止抢占——持自旋锁、硬/软中断上下文、显式 <code>preempt_disable</code>、以及 NMI。没有计数，抢占会在临界区中间把 per-CPU 假设拆掉。</p><p><span class="marginnote">抢占计数：关抢占、关软中断、在 IRQ 中，都会把计数抬高。为零才是「可在内核中被调度走」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置打开内核抢占。时钟或唤醒把 <code>TIF_NEED_RESCHED</code> 一类位置上。中断返回、或显式 <code>preempt_enable</code> 降到零时，检查并调用调度器。睡眠本来就会切换，与抢占无关。驱动在遍历无锁 per-CPU 链表时必须关抢占，否则会被迁到另一 CPU。</p>',8)),(a(),n(c,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20CHK%5B%22%E6%8A%A2%E5%8D%A0%E8%AE%A1%E6%95%B0%E4%B8%BA%E9%9B%B6%3F%22%5D%0A%20%20CHK%20--%3E%20SW%5B%22%E5%8F%AF%E5%88%87%E6%8D%A2%22%5D%0A%20%20CHK%20--%3E%20HOLD%5B%22%E6%8C%81%E9%94%81%E6%88%96%20IRQ%3A%20%E4%B8%8D%E5%8F%AF%E6%8A%A2%E5%8D%A0%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>本课不把 <code>PREEMPT_RT</code> 的全面睡眠锁替换写完，只钉「内核是否可在中途被抢」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>抢占把<a href="/cs/scheduling-metrics">调度指标</a>里的响应从「系统调用边界」推进到「内核内部可抢占点」。代价是：凡假设「不会在这里换线程、换 CPU」的代码都必须显式关抢占。与<a href="/cs/interrupt-bottom-half">中断下半部</a>叠加：软中断里仍不可睡，但可抢占内核在软中断外更早切换。实时对照课依赖这套点，否则 RM/EDF 只在用户态有效。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较各发行版默认抢占模型，不把锁依赖检测器的全部规则写成正文。用户抢占（时间片用完回到用户再切）一直存在；本课对象是<strong>内核执行途中</strong>被切。</p><p>后课默认：可抢占内核里，CPU 本地的无锁数据必须配合关抢占或关中断。如何把数据结构做成每 CPU 一份以避开锁，下一课讲 per-CPU 数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核抢占：在允许点从内核路径上被调度走。</li><li>自旋锁、IRQ、显式关抢占禁止切换。</li><li>per-CPU 无锁结构依赖这套计数，下一课展开。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const b=l(h,[["render",m]]);export{C as __pageData,b as default};
